--
-- Loads the demo source rows into staging. Idempotent: the batch's own
-- rows are deleted first, so re-running the loader cannot create the
-- duplicates that the duplicate-check test would then (correctly) flag.
-- The batch is supplied as :batch_id, so --batch-id actually works.
-- =====================================================================

DELETE FROM STG_CUSTOMER WHERE BATCH_ID = :batch_id;
DELETE FROM STG_POLICY WHERE BATCH_ID = :batch_id;
DELETE FROM STG_CLAIM WHERE BATCH_ID = :batch_id;

-- ---------- STG_CUSTOMER (30 rows) ----------

-- ---------- STG_POLICY (40 rows) ----------

-- ---------- STG_CLAIM (50 rows) ----------

-- Record the batch so file-to-stage reconciliation has expected counts.
DELETE FROM DQ_BATCH_METADATA WHERE BATCH_ID = :batch_id;
VALUES (:batch_id, 'CSV_FEED', 'data/*.csv', 120, 120, 0, 'LOADED');
